function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  validation: ValidationResult,
  sessionStore?: import('../../types/sessionStore.js').SessionStore,
  options?: {history?: {enabled: boolean}}
): void {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') {
    if (!options?.history?.enabled || !sessionStore?.listFor) {
      sendError(ws, ErrorCodes.UNSUPPORTED, 'History is not supported or is disabled');
      return;
    }
    void handleListSessions(ws, session, message, sessionStore);
  }
}

